import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.experimental.UtilityClass;

@Builder
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class Foo { // violation, the builder is nested and may use the private ctor
    private int x;
}

@Builder
class Bar { private int x; } // no violation, builder generates a package-private ctor

@Data
@NoArgsConstructor(access = AccessLevel.PRIVATE)
class Baz { private int x; } // violation, @Data does not generate a ctor if @NoArgsConstructor is present

@Data
class Qux { private final int x; } // no violation, public required args ctor

@UtilityClass
class Util { } // no violation, @UtilityClass makes the class final

public class Outer {
    @UtilityClass
    private static class InnerUtil { } // no violation, @UtilityClass makes the class final
}

